// ===== SETUP: edit these =====
const SECRET = "YOUR_SHARED_SECRET";   // any long random string, sent as &s=
const IG_HANDLE = "YOUR_IG_HANDLE";    // your Instagram account, without the @
const BOT_NAME = "DM Bot";             // name shown on the confirmation card
// Optional avatar for the card. iOS Shortcuts "Show Result" blocks remote images,
// so paste a data URI here (data:image/jpeg;base64,...). Leave empty for a plain circle.
const AVATAR = "";
// ==============================

const q = (($input.first().json && $input.first().json.query) || {});
const action = String(q.action || '').toLowerCase().trim();
// u can be a handle, an @handle, or a shared profile link
// (instagram.com/name?igsh=...).
function extractHandle(input) {
  const t = String(input || '').trim();
  if (!t) return '';
  if (/instagram\.com\/(p|reel|reels|stories)\//i.test(t)) return '';
  const m = t.match(/instagram\.com\/([a-zA-Z0-9._]+)/i);
  const h = (m ? m[1] : t.replace(/^@/, '')).toLowerCase();
  return /^[a-z0-9._]{1,30}$/.test(h) ? h : '';
}
const usernameRaw = extractHandle(q.u);
const provided = String(q.s || '').trim();
if (provided !== SECRET) {
  return [{ json: { ok: false, message: 'forbidden' } }];
}
const VALID_ACTIONS = ['off', 'on', 'reset', 'status'];
if (!VALID_ACTIONS.includes(action)) {
  return [{ json: { ok: false, message: `bad action. one of: ${VALID_ACTIONS.join(', ')}` } }];
}
if (!usernameRaw) {
  return [{ json: { ok: false, message: 'missing u (ig_username)' } }];
}
// Confirmation card for the iOS Shortcut. fmt=text gets plain text.
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const STATES = {
  on:      { color: '#22c55e', title: 'Bot ON',    sub: `${BOT_NAME} answers their next message.`, text: 'Bot ON for @H. It answers their next message.' },
  off:     { color: '#ef4444', title: 'Bot OFF',   sub: `${BOT_NAME} steps back. You've got the conversation.`, text: 'Bot OFF for @H. You have the conversation.' },
  reset:   { color: '#f5a524', title: 'Bot reset', sub: 'Memory wiped. It starts fresh on their next message.', text: 'Bot reset for @H. Memory wiped.' },
  unknown: { color: '#f5a524', title: 'Not found', sub: `They haven't DM'd you recently, so ${BOT_NAME} can't find them.`, text: `Can't find @H. They have to DM @${IG_HANDLE} first, then try again.` },
};
function card(kind, handle, fmt) {
  const s = STATES[kind];
  const h = String(handle).replace(/[^a-z0-9._]/g, '');
  if (fmt === 'text') return s.text.replace('@H', '@' + h);
  const pic = AVATAR ? `<img src="${esc(AVATAR)}" alt="">` : '<div class="ph"></div>';
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>html,body{margin:0;background:#0a0a0a;color:#f5f5f5;font-family:-apple-system,BlinkMacSystemFont,"Helvetica Neue",sans-serif;text-align:center}body{padding:32px 20px}.av{position:relative;display:inline-block}.av img,.av .ph{width:112px;height:112px;border-radius:50%;border:3px solid #f47c20;box-shadow:0 0 44px rgba(244,124,32,.45);display:block}.av .ph{background:#1c1c1e}.st{position:absolute;right:6px;bottom:6px;width:22px;height:22px;border-radius:50%;background:${s.color};border:3px solid #0a0a0a}.k{font-size:12px;letter-spacing:3px;font-weight:700;color:#f47c20;margin-top:18px}h1{font-size:30px;margin:6px 0 4px;font-weight:800}.h{font-size:18px;color:${s.color};font-weight:600}.s{font-size:15px;color:#8e8e93;margin:10px auto 0;max-width:280px;line-height:1.4}</style></head><body><div class="av">${pic}<span class="st"></span></div><div class="k">${esc(BOT_NAME.toUpperCase())}</div><h1>${s.title}</h1><div class="h">@${h}</div><div class="s">${esc(s.sub)}</div></body></html>`;
}
const fmt = String(q.fmt || '').toLowerCase() === 'text' ? 'text' : 'html';
return [{ json: {
  ok: true, action, ig_username: usernameRaw,
  reply_ok: STATES[action] ? card(action, usernameRaw, fmt) : '',
  reply_unknown: card('unknown', usernameRaw, fmt),
  content_type: fmt === 'text' ? 'text/plain; charset=utf-8' : 'text/html; charset=utf-8',
} }];

// Pull the original action+ig_username from Validate request (because
// the upstream HTTP call replaced $json with the n8n executions list).
const validated = $('Validate request').first().json || {};
const action = validated.action;
const target = String(validated.ig_username || '').toLowerCase().trim();

const allRuns = $('Fetch n8n executions').all();
let resolved = null;
let lastSeen = '';
let lastMsg = '';
for (const it of allRuns) {
  const exes = (it.json && it.json.data) || [];
  for (const ex of exes) {
    try {
      const body = ex.data.resultData.runData.Webhook[0].data.main[0][0].json.body;
      const ig = String(body.ig_username || '').toLowerCase().replace(/^@/, '').trim();
      if (ig !== target) continue;
      const started = ex.startedAt || '';
      if (!resolved || started > lastSeen) {
        resolved = body.id;
        lastSeen = started;
        lastMsg = (body.custom_fields && body.custom_fields['AI > User Messages']) || '';
      }
    } catch (e) {}
  }
}
return [{ json: {
  action,
  ig_username: target,
  resolved,
  last_seen: lastSeen,
  last_msg: lastMsg,
} }];

const action = $json.action;
const sid = $json.resolved;
let fields;
if (action === 'off') {
  // Same as the bot form: silence it and clear both bypasses so it
  // cannot sneak back on.
  fields = [
    { field_name: 'bot_paused', field_value: true },
    { field_name: 'force_on', field_value: false },
    { field_name: 'test_ai_until', field_value: 0 },
  ];
} else if (action === 'on') {
  // The bot is silent by default, so ON has to arm it (force_on), not just unpause.
  fields = [
    { field_name: 'bot_paused', field_value: false },
    { field_name: 'force_on', field_value: true },
  ];
} else if (action === 'reset') {
  fields = [
    { field_name: 'conversation_summary', field_value: null },
    { field_name: 'current_phase', field_value: 0 },
    { field_name: 'AI > Answer 1', field_value: null },
    { field_name: 'AI > Answer 2', field_value: null },
    { field_name: 'AI > Answer 3', field_value: null },
    { field_name: 'AI > Answer 4', field_value: null },
    { field_name: 'AI > Answer 5', field_value: null },
    { field_name: 'AI > Answer 6', field_value: null },
    { field_name: 'bot_paused', field_value: false },
  ];
} else {
  fields = null;
}
const body = fields ? JSON.stringify({ subscriber_id: Number(sid) || sid, fields }) : null;
return [{ json: { ...$json, mutation_body: body } }];

