const action = $('Build mutation body').first().json.action;
const handle = $('Resolve subscriber_id').first().json.ig_username;
const lastMsg = String($('Resolve subscriber_id').first().json.last_msg || '').slice(0, 120);
const labels = { on: '🟢 turned ON', off: '🔴 turned OFF', reset: '♻️ reset' };
const label = labels[action] || action;
const lines = [`IG DM bot ${label} for @${handle}`];
if (lastMsg) lines.push(`last msg: "${lastMsg}"`);
lines.push('via phone shortcut / dashboard control');
return [{ json: { slack_body: JSON.stringify({
  channel: "YOUR_SLACK_CHANNEL_ID", // a channel id (C...) or your own user id (U...) for a DM
  text: lines.join('\n'),
}) } }];
